typedef int T;

int nested_scopes(int x) {
  T outer = 0;
  {
    int T = 1;
    x += sizeof(T);
    {
      typedef long T;
      x += sizeof(T);
    }
    x += sizeof(T);
  }
  x += sizeof(T);
  for (int T = 0; T < sizeof(T); T++) {
    x += sizeof(T);
  }
  return x + sizeof(T) + outer;
}

int parameter_scope(int T) {
  return sizeof(T);
}

T after_function;

int statement_expression(void) {
  return ({ int T = 1; sizeof(T); }) + sizeof(T);
}

